mapper.select:
SELECT 
FROM ai_agent_chat_history
WHERE agent_id = #{agentId}
  AND (mac_address = #{macAddress}
       OR REPLACE(LOWER(IFNULL(mac_address,'')), ':', '_') = REPLACE(LOWER(IFNULL(#{macAddress},'')), ':', '_')
       OR REPLACE(LOWER(IFNULL(mac_address,'')), '_', ':') = REPLACE(LOWER(IFNULL(#{macAddress},'')), '_', ':'))
